use Illuminate\Database\Migrations\Migration;

/**
 * Seeds (or, on a re-run, upserts) the comprehensive Spanish (base column)
 * and English (translations->en) content of the three public legal
 * documents. This runs as a migration — not a Seeder — because
 * LandingPageController's public actions abort(404) when the row simply
 * does not exist yet (LandingPrivacyPolicy::first()/LandingTermsConditions::
 * first()/LandingRefundPolicy::first() with no firstOrCreate() fallback on
 * the public path), so the page must never go live without this content
 * already present.
 *
 * Idempotent: safe to run multiple times. An admin who has since edited a
 * field through Super Admin -> CMS keeps their edit; this migration only
 * fills fields that are still empty, using updateOrCreate + a "only fill
 * blanks" pass rather than blindly overwriting.
 */
return new class extends Migration
{
    public function up(): void
    {
        $this->seed(LandingTermsConditions::class, $this->termsContent());
        $this->seed(LandingPrivacyPolicy::class, $this->privacyContent());
        $this->seed(LandingRefundPolicy::class, $this->refundContent());
    }

    public function down(): void
    {
        // Intentionally a no-op: this migration only seeds/backfills content
        // on existing single-row CMS tables. Rolling it back must not delete
        // legal content an admin may have since edited live.
    }

    /**
     * @param class-string $modelClass
     * @param array<string, array{es: string, en: string}> $fields
     */
    private function seed(string $modelClass, array $fields): void
    {
        /** @var \Illuminate\Database\Eloquent\Model $row */
        $row = $modelClass::first();

        $attributes = [];
        $translationsChanged = false;
        $translations = $row?->getRawOriginal('translations');
        $translations = is_string($translations) ? (json_decode($translations, true) ?: []) : ($translations ?: []);

        foreach ($fields as $field => $copy) {
            $currentBase = $row?->getRawOriginal($field);
            if ($currentBase === null || trim((string) $currentBase) === '') {
                $attributes[$field] = $copy['es'];
            }

            $currentEn = $translations['en'][$field] ?? null;
            if ($currentEn === null || trim((string) $currentEn) === '') {
                $translations['en'][$field] = $copy['en'];
                $translationsChanged = true;
            }
        }

        if ($translationsChanged) {
            $attributes['translations'] = $translations;
        }

        if (! $row) {
            $attributes['is_active'] = true;
            $attributes['last_updated'] = now()->toDateString();
            $modelClass::create($attributes);

            return;
        }

        if (! empty($attributes)) {
            $row->forceFill($attributes)->save();
        }
    }

